out=['# Repository atlas and evidence index','This atlas describes the selected first-party reading snapshot of4 November2026. It maps conceptual responsibilities, execution order, inputs, consumers, status and tests. The actual source copy contains213 files; evidence/snapshot.json identifies their bytes and the dirty working tree. This is a reading set, not a complete Git clone or operational backup. No raw telemetry, dependency tree, credentials or prepared feature cache is bundled.','## Execution order','Replay path: session identity → local projection and channel synchronization → crossing/leg/manoeuvre reconstruction → replay and historical exports → catalogs and browser. Forecast path branches from raw causal observations → sealed dataset → state and cutoff-aware labels → strength/completion models → correlated simulation or declared reference → tournament adaptation → validated immutable publication. Historical summaries are not causal live features. Environment acquisition and report/previews generation are separate refresh paths.','## Explicit subsystem coverage','Every row below was routed through project contracts and focused current source review. “Inspected” means key paths and relevant tests were examined, not every line formally proved. The textbook contains the deep explanations and five interface journeys. The complete manifest lists the copied files without pretending a directory listing explains them.','| Subsystem | Phase | Status | Explained |','| --- | --- | --- | --- |']
out += [f'| {name} | {phase} | {status} | Inspected and explained below |' for name,files,phase,purpose,tests,status in rows]
for name,files,phase,purpose,tests,status in rows:
    out += ['## '+name,purpose,f'Entry points: {files}. Phase: {phase}. Status: {status}. Test route: {tests}.']
    refs=[]
    for file in files.split(', '):
        assert (P/'source'/file).is_file(),file
        refs.append(f'[{file}:L1-L1]')
    assert (P/'source'/tests).is_file(),tests
    out += [' '.join(refs)+f' [{tests}:L1-L1]']
glossary={
'Session':'One source race/session export; a filename is not a guaranteed date.', 'Boat-race':'One boat observed in one race; the historical unit is not a frame.', 'Scheduled entry':'A member of the scheduled forecast field, even without replay telemetry.', 'Frame':'A regular100 ms replay state, often interpolated.', 'Gate':'A directed line between identified marks in an ordered course sequence.', 'Leg':'A course segment bounded by start/checkpoint timing.', 'Tack':'Upwind change of wind side, subject to detector context and coverage.', 'Gybe':'Downwind change of wind side.', 'Heading':'Hull orientation bearing clockwise from north.', 'COG':'Course over ground, the direction of motion.', 'SOG / sog_mean_kt':'Speed over ground; its canonical mean needs an eligible source-supported window.', 'TWD':'True wind direction from which wind comes.', 'TWS':'True wind speed, with source and units retained.', 'TWA':'Derived wind angle relative to heading; not interchangeable with velocity angle.', 'Course-axis VMG':'Velocity projected onto the course axis; raw sign can differ by leg direction.', 'Wind-relative VMG':'Velocity projection relative to wind, with its own sign convention.', 'x,y':'Local east,north metres with exported origin and coefficients.', 'timestamp_ms':'Integer milliseconds; distinguish seconds in durations.', 'Checkpoint gap':'Difference in passage times at a shared checkpoint.', 'Continuous gap':'A moving geometry/speed estimate, not a checkpoint observation.', 'OCS':'Start-side/source-state concept; a visual early intersection alone is insufficient.', 'DNS':'Did not start; preserve field membership and missing telemetry separately.', 'RET / DNF':'Retired/nonfinish labels with source and evidence limits.', 'Calculated result':'Reconstructed classification, not independently verified official results.', 'quality':'Provenance/availability category such as derived, reconstructed, partial or unavailable.', 'coverage_s':'Supported seconds under the owning metric definition.', 'sample_count':'Event/leg or other defined sample count; not necessarily telemetry frames.', 'matched_legs':'Eligible same-leg comparisons admitted into an index.', 'peer_mean':'Equal-boat other-boat baseline within eligible scope.', 'peer_ids':'Named contributing boats; selected boat excluded.', 'index':'100 times selected/peer ratio, averaged equally over eligible legs.', 'overall_index':'Aggregate defined only under required dimension availability; not ability.', 'retention':'Minimum versus entry-speed ratio over selected eligible detected events.', 'debrief':'Ranked observed review items with replay links, not causal advice.', 'tactical_insights':'Exported recorded trend snapshots; projections remain gated.', 'schema_version':'Structural contract version, distinct from formula/method version.', 'method_version':'Version of scientific calculation or export method.', 'Historical View':'Index/cohort view over boat-races, not frames.', 'A / B':'Primary selection and explicit comparison selection; not forecast team rankings.', 'Grid / Map':'Direct metre canvas versus geographic base; Grid avoids tile requests.', 'Enhanced':'Readable display scaling, separate from physical contact calculation.', 'Keep Clear':'Modeled safety envelope; overlap is not an official ruling.', 'training_cutoff':'Only prior available evidence may fit the model.', 'available_at':'Information publication/availability time, distinct from observation time.', 'Plackett-Luce':'Sequential positive-weight ranking reference.', 'correlated_mc':'Joint Monte Carlo candidate with shared uncertainty, currently provisional.', 'N':'Complete scheduled field size; nonfinish score convention uses N.', 'expected_position':'Unconditional expected scheduled-field score including nonfinish.', 'Brier':'Summed multiclass squared probability error under this evaluator.', 'Log loss':'Negative logarithm of probability assigned to the observed winner.', 'RPS':'Ranked probability score for an ordered distribution, normalized by contract.', 'Calibration':'Empirical frequency agreement requiring independent outcomes.', 'Pseudoreplication':'Treating dependent repeated measurements as independent evidence.', 'Monte Carlo error':'Numerical finite-trial sampling uncertainty conditional on a model.', 'Transfer loading':'Assumed AC40-to-AC75 strength relationship, not measured correlation.', 'Rule bound':'Conservative allocation of unresolved tournament mass.', 'Scenario envelope':'Coordinatewise extremes across assumptions; endpoints can differ in origin.', 'model_ref':'Canonical model-card content hash.', 'source_manifest_hash':'Canonical manifest identity; does not imply all raw bytes rehashed today.', 'scenario_hash':'Declared scenario input identity, distinct from byte SHA of a file.', 'Immutable object':'Content-addressed publication retained after active index changes.', 'Atomic index':'Validated pointer switch using replacement, with prior publication surviving failures.', 'Publication lock':'Shared local job ownership guard including publisher child process.', 'Static hosting':'Can display saved objects; new generation needs the prepared local service.'}
out += ['## Cross domain glossary','| Term or field | Meaning and caution |','| --- | --- |']+[f'| {k} | {v} |' for k,v in glossary.items()]
out += ['## Evidence routes and preservation','Start with [frozen source navigation](source/_SOURCE_INDEX.html), [the snapshot manifest](evidence/snapshot.json), [bounded actual case evidence](evidence/data_metrics_review.json), [current model/evaluation findings](evidence/forecast_review.json), [UI findings](evidence/interface_review.json), and [fresh verification](VERIFICATION.html). Source citations above point to entry points; detailed line ranges in the textbook point to producing functions. Existing notices are preserved. No top-level repository license or independent official-result verification is invented.']
(P/'03_Repository_Atlas.md').write_text('\n\n'.join(out)+'\n',encoding='utf8')
